import XCTest

private final class Editor {
    var title = "Draft"
    var onSave: (() -> String)?

    init() {
        onSave = { [weak self] in
            self?.title ?? ""
        }
    }
}

final class EditorLifetimeTests: XCTestCase {
    func testEditorIsReleased() {
        var editor: Editor? = Editor()
        weak var observed = editor
        XCTAssertEqual(editor?.onSave?(), "Draft")
        editor = nil
        XCTAssertNil(observed)
    }
}

